// Additional offline audit assertions against the freshly built library.
// Fixed synthetic inputs only; stdout contains row ids, never key material.
use zec_payroll::{*,money::{Zat,MAX_MONEY},date::Date,schedule::{Schedule,Cadence},employee::Employee};
fn d(s:&str)->Date{Date::parse(s).unwrap()}
fn batch()->Vec<Employee>{csv::parse_payroll_csv(&std::fs::read_to_string("e2e/fixtures/roster.csv").unwrap()).unwrap()}
fn engine()->Engine{let mut e=Engine::new(CapPolicy::default());for (i,(id,amount)) in [("alice",150_000_000),("bob",200_000_000),("carol",25_000_000)].into_iter().enumerate(){let mut p=batch()[i%2].clone();p.id=id.into();p.pay=Zat(amount);e.add_employee(p).unwrap()}e.add_schedule(Schedule{id:"biweekly".into(),cadence:Cadence::Biweekly,anchor:d("2026-10-02"),employee_ids:vec!["alice".into(),"bob".into(),"carol".into()]}).unwrap();e}
fn run(id:&str,f:impl FnOnce()+std::panic::UnwindSafe){let ok=std::panic::catch_unwind(f).is_ok();println!("{id} {}",if ok{"PASS"}else{"FAIL"});}
