 run("CORE-DATE",||{assert_eq!(d("1970-01-01").to_days(),0);for n in [-800000,-1,0,1,20000,3000000]{assert_eq!(Date::from_days(n).to_days(),n)}assert_eq!(d("2026-10-20").add_days(14),d("2026-11-03"));assert!(Date::parse("2028-02-29").is_some());for s in ["2026-02-29","2100-02-29","2026-13-01","garbage"]{assert!(Date::parse(s).is_none())}});
 run("CORE-SCHEDULE",||{let s=|cadence,anchor|Schedule{id:"s".into(),cadence,anchor:d(anchor),employee_ids:vec![]};assert_eq!(s(Cadence::Weekly,"2026-10-05").next_pay_date(d("2026-10-05")),d("2026-10-12"));let b=s(Cadence::Biweekly,"2026-10-02");assert!(b.is_pay_date(d("2026-10-16")));assert!(!b.is_pay_date(d("2026-10-09")));assert!(!b.is_pay_date(d("2026-09-18")));assert_eq!(b.next_pay_date(d("2026-10-16")),d("2026-10-30"));let m=s(Cadence::Monthly{day:31},"2020-01-31");for day in ["2026-02-28","2028-02-29","2026-04-30"]{assert!(m.is_pay_date(d(day)));assert!(m.next_pay_date(d(day))>d(day))}});
 run("CORE-EMPLOYEE",||{let mut b=batch()[0].clone();b.id="".into();assert_eq!(b.validate().unwrap_err().to_string(),"employee id is empty");b.id="id".into();b.name="".into();assert_eq!(b.validate().unwrap_err().to_string(),"employee name is empty");b.name="name".into();b.memo="x".repeat(512);assert!(b.validate().is_ok());b.memo.push('x');let s=b.validate().unwrap_err().to_string();assert!(s.contains("id")&&s.contains("513"))});
