 run("CORE-ENGINE-STATUS",||{let mut e=engine();let id=e.plan_scheduled("biweekly",d("2026-10-16")).unwrap();assert!(matches!(e.mark_broadcast(id,&"ab".repeat(32)),Err(EngineError::BadTransition{..})));assert!(e.mark_failed(id,"x").is_err());assert_eq!(e.run(id).unwrap().status,RunStatus::Draft);e.approve(id).unwrap();assert!(e.approve(id).is_err());assert!(matches!(e.mark_broadcast(id,"bad"),Err(EngineError::BadTxid(_))));assert_eq!(e.run(id).unwrap().status,RunStatus::Approved);e.mark_broadcast(id,&"AB".repeat(32)).unwrap();e.mark_confirmed(id,4521181).unwrap();assert_eq!(e.run(id).unwrap().status,RunStatus::Confirmed{txid:"ab".repeat(32),height:4521181});assert!(e.mark_failed(id,"x").is_err());assert!(matches!(e.approve(99),Err(EngineError::UnknownRun(99))))});
